export type Post = {
  id: string;
  title: string;
  body: string;
  createdAt: number;
};

const posts: Post[] = [];

export function getPosts(): Post[] {
  return [...posts];
}

export function addPost(title: string, body: string): Post {
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    body,
    createdAt: Date.now(),
  };
  posts.push(post);
  return post;
}

